#include <bits/stdc++.h>
using namespace std;

int digitValue(char ch) {
    if (isalpha(static_cast<unsigned char>(ch)))
        return toupper(static_cast<unsigned char>(ch)) - 'A' + 10;
    return ch - '0';
}

bool belowLimit(const string& s, int base, int limit) {
    int value = 0;
    for (char ch : s) {
        int digit = digitValue(ch);
        if (value > (limit - 1 - digit) / base)
            return false;
        value = value * base + digit;
    }
    return true;
}

bool validTime(const string& hours, const string& minutes, int base) {
    return belowLimit(hours, base, 24) &&
           belowLimit(minutes, base, 60);
}

string trimLeadingZeros(const string& s) {
    size_t pos = s.find_first_not_of('0');
    return pos == string::npos ? "0" : s.substr(pos);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    size_t colon = s.find(':');
    string hours = trimLeadingZeros(s.substr(0, colon));
    string minutes = trimLeadingZeros(s.substr(colon + 1));

    int maxDigit = 0;
    for (char ch : s) {
        if (ch != ':')
            maxDigit = max(maxDigit, digitValue(ch));
    }

    int base = maxDigit + 1;

    if (hours.size() == 1 && minutes.size() == 1) {
        cout << (validTime(hours, minutes, base) ? -1 : 0) << '\n';
        return 0;
    }

    vector<int> validBases;
    while (validTime(hours, minutes, base)) {
        validBases.push_back(base);
        ++base;
    }

    if (validBases.empty()) {
        cout << 0 << '\n';
    } else {
        for (int validBase : validBases)
            cout << validBase << ' ';
        cout << '\n';
    }

    return 0;
}

